def svg(clase="logotipo", titulo="th3b1gbr0th3r IT"):
    """SVG inline del logotipo: texto en currentColor y «IT» en tostado. Alto controlado por CSS."""
    return (f'<svg class="{clase}" viewBox="0 0 {ANCHO} {ALTO}" role="img" aria-label="{titulo}" focusable="false">'
            f'<path d="{TRAZOS}" fill="currentColor"/><path class="logo-it" d="{ACENTO_TRAZOS}" fill="#b45309"/></svg>')


def definicion(id_="logo-trazos"):
    """Bloque oculto con los trazos, una vez por página; los logotipos de la página lo reutilizan con uso()."""
    return (f'<svg width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs><g id="{id_}">'
            f'<path d="{TRAZOS}" fill="currentColor"/><path class="logo-it" d="{ACENTO_TRAZOS}" fill="#b45309"/></g></defs></svg>')


def uso(clase="logotipo", id_="logo-trazos"):
    return f'<svg class="{clase}" viewBox="0 0 {ANCHO} {ALTO}" aria-hidden="true" focusable="false"><use href="#{id_}"/></svg>'


def _generar(ruta_fuente):  # pragma: no cover (herramienta manual)
    from fontTools.pens.svgPathPen import SVGPathPen
    from fontTools.pens.transformPen import TransformPen
    from fontTools.ttLib import TTFont

    f = TTFont(ruta_fuente)
    gs, cmap, hmtx = f.getGlyphSet(), f.getBestCmap(), f["hmtx"]
    asc = f["OS/2"].sCapHeight + 60  # margen sobre las astas (t, h, b)
    desc = 230  # bajada de la g
    espaciado = 8  # unidades de fuente entre letras

    def trazar(texto, x):
        pen = SVGPathPen(gs, ntos=lambda v: f"{v:.0f}")
        for ch in texto:
            g = cmap[ord(ch)]
            gs[g].draw(TransformPen(pen, (1, 0, 0, -1, x, asc)))
            x += hmtx[g][0] + espaciado
        return pen.getCommands(), x

    trazos, x = trazar(TEXTO, 0)
    acento, x = trazar(ACENTO, x + 200)  # espacio entre la marca y «IT»
    print(f"TRAZOS = {trazos!r}\nACENTO_TRAZOS = {acento!r}\nANCHO = {round(x)}\nALTO = {asc + desc}\nBASE = {asc}")


if __name__ == "__main__":
    import sys

    _generar(sys.argv[1])
